-- Dedicated advertising records. Idempotent; run in the admin control schema.
CREATE TABLE IF NOT EXISTS ad_inventory_lock (
  id TINYINT UNSIGNED PRIMARY KEY
);
INSERT IGNORE INTO ad_inventory_lock VALUES (1);
CREATE TABLE IF NOT EXISTS ad_placements (
  id VARCHAR(80) PRIMARY KEY,
  scene VARCHAR(80) NOT NULL,
  definition JSON NOT NULL
);
CREATE TABLE IF NOT EXISTS ad_advertisers (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(160) NOT NULL,
  contact VARCHAR(254) NOT NULL DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS ad_creatives (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  advertiser_id BIGINT UNSIGNED NOT NULL,
  alt_text VARCHAR(240) NOT NULL,
  destination VARCHAR(2048) NOT NULL,
  width INT UNSIGNED NOT NULL,
  height INT UNSIGNED NOT NULL,
  image MEDIUMBLOB NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (advertiser_id) REFERENCES ad_advertisers(id)
);
CREATE TABLE IF NOT EXISTS ad_campaigns (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  advertiser_id BIGINT UNSIGNED NOT NULL,
  name VARCHAR(160) NOT NULL,
  status ENUM('draft','live','paused') NOT NULL DEFAULT 'draft',
  revision INT UNSIGNED NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (advertiser_id) REFERENCES ad_advertisers(id)
);
CREATE TABLE IF NOT EXISTS ad_bookings (
  campaign_id BIGINT UNSIGNED NOT NULL,
  placement_id VARCHAR(80) NOT NULL,
  creative_id BIGINT UNSIGNED NOT NULL,
  starts_at BIGINT NOT NULL,
  ends_at BIGINT NOT NULL,
  PRIMARY KEY (campaign_id),
  INDEX ad_schedule (placement_id, starts_at, ends_at),
  FOREIGN KEY (campaign_id) REFERENCES ad_campaigns(id),
  FOREIGN KEY (placement_id) REFERENCES ad_placements(id),
  FOREIGN KEY (creative_id) REFERENCES ad_creatives(id),
  CHECK (ends_at > starts_at)
);

